"""Server-authoritative ground, swim and vehicle movement.

Humans and bots go through the same functions with the same speeds. Clients (and bot AI) only
set an intent: `Participant.move_x/move_y`, `sprinting`, and stance requests. The server
normalises the intent, applies the configured speed, clamps to the map and slides against
blockers. A tick never moves a participant further than `speed * dt`.

Doors: in the development maps doors are state only. They are NOT blockers and do not affect
movement or line of sight; `toggle_door` just flips `Door.open` for views and events.

Every action function returns `(ok, detail)` and never raises for bad client input.
"""

import math
from collections.abc import Callable

from solo_engine.geometry import clamp_to_map, distance, inside_any, normalize
from solo_engine.model import (
    Door,
    LifeState,
    MapDefinition,
    Participant,
    SoloMatch,
    Stance,
    Vehicle,
)
from solo_engine.spatial import blocker_index

DOOR_REACH = 3.0  # metres from a door point to toggle it
VEHICLE_REACH = 4.0  # metres from a vehicle to enter it
FUEL_PER_METRE = 0.05  # fuel units used per metre driven
MAX_SUBSTEP = 0.5  # metres per collision substep, so fast movers cannot tunnel through rocks
EXIT_OFFSETS = (2.5, 4.0, 6.0)  # radii tried when placing a participant beside a vehicle


def _finite(*values: float) -> bool:
    return all(isinstance(v, (int, float)) and math.isfinite(v) for v in values)


def _intent(p: Participant) -> tuple[float, float]:
    """Requested direction as a unit vector, or (0, 0). Garbage input counts as no input."""
    if not _finite(p.move_x, p.move_y):
        return 0.0, 0.0
    return normalize(p.move_x, p.move_y)


def ground_speed(match: SoloMatch, p: Participant) -> float:
    """Metres per second for a grounded participant in its current stance and medium."""
    config = match.config
    if p.swimming:
        return config.swim_speed
    if p.stance == Stance.PRONE:
        return config.prone_speed
    if p.stance == Stance.CROUCH:
        return config.crouch_speed
    return config.sprint_speed if p.sprinting else config.walk_speed


Blocked = Callable[[float, float], bool]


def _slide(x: float, y: float, nx: float, ny: float, blocked: Blocked) -> tuple[float, float]:
    """geometry.slide with a point test: go to (nx, ny), else each axis alone, else stay."""
    if not blocked(nx, ny):
        return nx, ny
    if not blocked(nx, y):
        return nx, y
    if not blocked(x, ny):
        return x, ny
    return x, y


def _ground_blocked(game_map: MapDefinition) -> Blocked:
    return blocker_index(game_map).contains


def _vehicle_blocked(game_map: MapDefinition) -> Blocked:
    contains = blocker_index(game_map).contains
    water = game_map.water
    return lambda x, y: contains(x, y) or inside_any(x, y, water)


def _move(
    x: float, y: float, dx: float, dy: float, length: float, size: float, blocked: Blocked
) -> tuple[float, float]:
    """Advance up to `length` metres along (dx, dy), clamped to the map, sliding on solids.

    `blocked(x, y)` is the solid test (the map's cached blocker index, plus water for vehicles).
    """
    steps = max(1, math.ceil(length / MAX_SUBSTEP))
    part = length / steps
    for _ in range(steps):
        nx, ny = clamp_to_map(x + dx * part, y + dy * part, size)
        nx, ny = _slide(x, y, nx, ny, blocked)
        if (nx, ny) == (x, y):
            break
        x, y = nx, ny
    return x, y


def _update_swimming(game_map: MapDefinition, p: Participant) -> None:
    p.swimming = inside_any(p.x, p.y, game_map.water)
    if p.swimming:
        p.stance = Stance.STAND
        p.sprinting = False


def step_ground(match: SoloMatch, p: Participant, dt: float) -> None:
    """Advance one grounded participant by `dt` seconds. Other life states are ignored."""
    if p.life != LifeState.GROUNDED or not _finite(dt) or dt <= 0:
        return
    game_map = match.map
    _update_swimming(game_map, p)
    dx, dy = _intent(p)
    if dx == 0.0 and dy == 0.0:
        return
    if p.stance != Stance.STAND:
        p.sprinting = False
    speed = ground_speed(match, p)
    nx, ny = _move(p.x, p.y, dx, dy, speed * dt, game_map.size, _ground_blocked(game_map))
    travelled = distance(p.x, p.y, nx, ny)
    p.x, p.y = nx, ny
    p.yaw = math.atan2(dy, dx)
    p.stats.distance_travelled += travelled
    _update_swimming(game_map, p)


def step_waiting(match: SoloMatch, p: Participant, dt: float) -> None:
    """Walk one participant around the preparation island by `dt` seconds.

    Only WAITING participants move. Same speed rules as the ground (stance, sprint), sliding on
    blockers, and every substep is clamped into `match.map.prep_island`, so a participant can
    walk along its edge but never leave it. No swimming: the island has no water.
    """
    if p.life != LifeState.WAITING or not _finite(dt) or dt <= 0:
        return
    dx, dy = _intent(p)
    if dx == 0.0 and dy == 0.0:
        return
    if p.stance != Stance.STAND:
        p.sprinting = False
    game_map = match.map
    island = game_map.prep_island
    length = ground_speed(match, p) * dt
    steps = max(1, math.ceil(length / MAX_SUBSTEP))
    part = length / steps
    blocked = _ground_blocked(game_map)
    x, y = p.x, p.y
    for _ in range(steps):
        nx = min(max(x + dx * part, island.min_x), island.max_x)
        ny = min(max(y + dy * part, island.min_y), island.max_y)
        nx, ny = _slide(x, y, nx, ny, blocked)
        if (nx, ny) == (x, y):
            break
        x, y = nx, ny
    p.stats.distance_travelled += distance(p.x, p.y, x, y)
    p.x, p.y = x, y
    p.yaw = math.atan2(dy, dx)


def _occupants(match: SoloMatch, vehicle: Vehicle) -> list[Participant]:
    ids = ([vehicle.driver_id] if vehicle.driver_id else []) + list(vehicle.passenger_ids)
    return [match.participants[i] for i in ids if i in match.participants]


def _sync_riders(match: SoloMatch, vehicle: Vehicle, travelled: float) -> None:
    for rider in _occupants(match, vehicle):
        rider.x, rider.y, rider.z = vehicle.x, vehicle.y, 0.0
        rider.stats.distance_travelled += travelled


def step_vehicle(match: SoloMatch, p: Participant, dt: float) -> None:
    """Drive the vehicle `p` is driving. Passengers ride along. Non-drivers are only synced."""
    if p.life != LifeState.IN_VEHICLE or p.vehicle_id is None or not _finite(dt) or dt <= 0:
        return
    vehicle = match.vehicles.get(p.vehicle_id)
    if vehicle is None:
        return
    if vehicle.driver_id != p.participant_id:
        p.x, p.y, p.z = vehicle.x, vehicle.y, 0.0
        return
    dx, dy = _intent(p)
    if (dx == 0.0 and dy == 0.0) or vehicle.health <= 0 or vehicle.fuel <= 0:
        _sync_riders(match, vehicle, 0.0)
        return
    reach = min(match.config.vehicle_speed * dt, vehicle.fuel / FUEL_PER_METRE)
    nx, ny = _move(vehicle.x, vehicle.y, dx, dy, reach, match.map.size, _vehicle_blocked(match.map))
    travelled = distance(vehicle.x, vehicle.y, nx, ny)
    vehicle.x, vehicle.y = nx, ny
    vehicle.yaw = math.atan2(dy, dx)
    vehicle.fuel = max(0.0, vehicle.fuel - travelled * FUEL_PER_METRE)
    p.yaw = vehicle.yaw
    _sync_riders(match, vehicle, travelled)


def set_stance(p: Participant, stance: Stance | str) -> tuple[bool, str]:
    """Change stance. Crouch and prone are refused while swimming or in a vehicle."""
    try:
        wanted = Stance(stance)
    except ValueError:
        return False, "invalid stance"
    if not p.alive:
        return False, "eliminated"
    if p.life not in (LifeState.GROUNDED, LifeState.IN_VEHICLE):
        return False, "not on the ground"
    if wanted != Stance.STAND and p.life == LifeState.IN_VEHICLE:
        return False, "in vehicle"
    if wanted != Stance.STAND and p.swimming:
        return False, "swimming"
    p.stance = wanted
    if wanted != Stance.STAND:
        p.sprinting = False
    return True, wanted.value


def build_doors(game_map: MapDefinition) -> dict[str, Door]:
    """Closed doors for every door point of a map, ids `door-<index>`."""
    return {f"door-{i}": Door(f"door-{i}", x, y) for i, (x, y) in enumerate(game_map.door_points)}


def toggle_door(match: SoloMatch, p: Participant, door_id: str) -> tuple[bool, str]:
    """Open or close a door within reach. Doors are state only; they never block movement."""
    if p.life != LifeState.GROUNDED:
        return False, "not on the ground"
    door = match.doors.get(door_id) if isinstance(door_id, str) else None
    if door is None:
        return False, "unknown door"
    if distance(p.x, p.y, door.x, door.y) > DOOR_REACH:
        return False, "too far"
    door.open = not door.open
    match.emit("door_toggled", door_id=door.door_id, participant_id=p.participant_id, open=door.open)
    return True, "open" if door.open else "closed"


def enter_vehicle(match: SoloMatch, p: Participant, vehicle_id: str) -> tuple[bool, str]:
    """Take the driver seat if free, else a passenger seat. Needs reach, a free seat, health."""
    if p.life != LifeState.GROUNDED:
        return False, "not on the ground"
    vehicle = match.vehicles.get(vehicle_id) if isinstance(vehicle_id, str) else None
    if vehicle is None:
        return False, "unknown vehicle"
    if vehicle.health <= 0:
        return False, "vehicle destroyed"
    if distance(p.x, p.y, vehicle.x, vehicle.y) > VEHICLE_REACH:
        return False, "too far"
    taken = (1 if vehicle.driver_id else 0) + len(vehicle.passenger_ids)
    if taken >= vehicle.seats:
        return False, "vehicle full"
    if vehicle.driver_id is None:
        vehicle.driver_id = p.participant_id
        seat = "driver"
    else:
        vehicle.passenger_ids.append(p.participant_id)
        seat = "passenger"
    p.life = LifeState.IN_VEHICLE
    p.vehicle_id = vehicle.vehicle_id
    p.stance, p.sprinting, p.swimming = Stance.STAND, False, False
    p.x, p.y, p.z = vehicle.x, vehicle.y, 0.0
    match.emit("vehicle_entered", vehicle_id=vehicle.vehicle_id, participant_id=p.participant_id, seat=seat)
    return True, seat


def _exit_point(game_map: MapDefinition, vehicle: Vehicle) -> tuple[float, float]:
    """First open point around the vehicle, starting at its left side. Falls back to the vehicle."""
    for radius in EXIT_OFFSETS:
        for k in range(8):
            angle = vehicle.yaw + math.pi / 2 + k * math.pi / 4
            x = vehicle.x + math.cos(angle) * radius
            y = vehicle.y + math.sin(angle) * radius
            if not (0.0 <= x <= game_map.size and 0.0 <= y <= game_map.size):
                continue
            if not inside_any(x, y, game_map.blockers) and not inside_any(x, y, game_map.water):
                return x, y
    return vehicle.x, vehicle.y


def exit_vehicle(match: SoloMatch, p: Participant) -> tuple[bool, str]:
    """Leave the seat and stand on open ground beside the vehicle.

    A driver leaving frees the driver seat; passengers keep their seats and are not promoted.
    """
    if p.life != LifeState.IN_VEHICLE:
        return False, "not in a vehicle"
    vehicle = match.vehicles.get(p.vehicle_id) if p.vehicle_id else None
    if vehicle is not None:
        if vehicle.driver_id == p.participant_id:
            vehicle.driver_id = None
        if p.participant_id in vehicle.passenger_ids:
            vehicle.passenger_ids.remove(p.participant_id)
        p.x, p.y = _exit_point(match.map, vehicle)
    p.z = 0.0
    p.life = LifeState.GROUNDED
    p.vehicle_id = None
    _update_swimming(match.map, p)
    match.emit("vehicle_exited", vehicle_id=vehicle.vehicle_id if vehicle else None, participant_id=p.participant_id)
    return True, "exited"
